import {jsonSafeStorage} from '@github-ui/safe-storage'
import {useMemo} from 'react'

export function useLocalStorageCache<T>(cacheKey: string) {
  const safeLocalStorage = useMemo(() => jsonSafeStorage<T>('localStorage'), [])

  const getLocalStorageValue = (subKey: string) => {
    return safeLocalStorage.getItem(`${cacheKey}+${subKey}`) ?? undefined
  }

  const setLocalStorageValue = (subKey: string, updated_value: T) => {
    safeLocalStorage.setItem(`${cacheKey}+${subKey}`, updated_value)
  }

  return {getLocalStorageValue, setLocalStorageValue}
}
