import {CopilotAssignmentModal} from '@github-ui/agent-sessions/components/copilot-assignment/CopilotAssignmentModal'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getIssueStateIcon} from '@github-ui/list-view-items-issues-prs/StateIcon'
import {CommentIcon, AgentIcon, CopilotIcon} from '@primer/octicons-react'
import {RelativeTime} from '@primer/react'

import {
  DashboardListItem,
  DashboardListItemTitle,
  DashboardListItemDescription,
  DashboardListItemLeadingVisual,
  DashboardListItemActions,
  DashboardListItemTrailingActionsMenu,
  DashboardListItemStatus,
} from './DashboardListView'
import type {DashboardIssue} from '../types'
import {useState, useRef, useMemo} from 'react'
import styles from '../DashboardLists.module.css'
import viewStyles from './DashboardListView.module.css'
import {useOpenCopilotChat} from '../hooks/useOpenCopilotChat'
import {useQueryClient} from '@github-ui/react-query'
import {issuesBaseQuery} from './issues-constants'
import {agentTasksQueryKey} from '@github-ui/agent-sessions/hooks/useTasks'
import {useDashboardAnalytics} from '../hooks/useDashboardAnalytics'

const DASHBOARD_ISSUE_LIST_ITEM_CHAT_ACTION = 'dashboard-issue-list-item-chat-action'

interface IssueListItemProps {
  issue: DashboardIssue
  onTitleClick: () => void
  showCopilotChatActions?: boolean
}

export function IssueListItem({issue, onTitleClick, showCopilotChatActions}: IssueListItemProps) {
  const repoNameWithOwner = `${issue.repository.ownerLogin}/${issue.repository.name}`
  const [isCopilotModalOpen, setIsCopilotModalOpen] = useState(false)
  const actionButtonRef = useRef<HTMLButtonElement>(null)
  const {openCopilotChatWithIssue} = useOpenCopilotChat()
  const {icon: Icon, color, description} = useMemo(() => getIssueStateIcon('OPEN'), [])
  const queryClient = useQueryClient()

  // Construct repository object for CopilotAssignmentModal
  const repository = {
    name: issue.repository.name,
    owner: {
      login: issue.repository.ownerLogin,
    },
  }

  const handleCopilotAssignmentComplete = async () => {
    setIsCopilotModalOpen(false)
    queryClient.invalidateQueries({queryKey: [issuesBaseQuery]})
    queryClient.invalidateQueries({queryKey: agentTasksQueryKey})
  }

  const handleModalClose = () => {
    setIsCopilotModalOpen(false)
  }

  const {sendDashboardClickAnalyticsEvent} = useDashboardAnalytics()
  const onSelectOpenInCopilotChat = () => {
    openCopilotChatWithIssue(issue, DASHBOARD_ISSUE_LIST_ITEM_CHAT_ACTION)
    sendDashboardClickAnalyticsEvent('open_issue_in_copilot_chat')
  }
  const onSelectAssignToCopilot = () => {
    setIsCopilotModalOpen(true)
    sendDashboardClickAnalyticsEvent('assign_issue_to_copilot')
  }

  const createdTime = new Date(issue.createdAt).setSeconds(0, 0)
  const updatedTime = new Date(issue.updatedAt).setSeconds(0, 0)
  const timestampLabel = createdTime !== updatedTime ? 'Updated ' : 'Created '

  return (
    <>
      <CopilotAssignmentModal
        isOpen={isCopilotModalOpen}
        onClose={handleModalClose}
        repository={repository}
        issueNumbers={[issue.number]}
        onAssignmentComplete={handleCopilotAssignmentComplete}
        returnFocusRef={actionButtonRef}
      />
      <DashboardListItem className={viewStyles.fadeIn}>
        <DashboardListItemLeadingVisual>
          <div style={{color}}>
            <Icon aria-label={description} fill={color} />
          </div>
        </DashboardListItemLeadingVisual>
        <DashboardListItemTitle href={issue.permalink} onClick={onTitleClick}>
          {issue.title}
        </DashboardListItemTitle>
        <DashboardListItemDescription>
          {`${repoNameWithOwner}#${issue.number} · Opened by ${issue.author} · `}
          {timestampLabel}
          <RelativeTime format="relative" datetime={issue.updatedAt} />
          {issue.assignedToCopilot ? (
            <>
              {' · '}
              <DashboardListItemStatus>
                <span className={styles.assignedToCopilotStatus}>
                  <CopilotIcon size={18} className={styles.copilotIcon} />
                  <span className={styles.assignedToCopilotText}>Assigned to Copilot</span>
                </span>
              </DashboardListItemStatus>
            </>
          ) : null}
        </DashboardListItemDescription>
        <DashboardListItemActions>
          {issue.commentCount > 0 && (
            <div>
              <div
                className={!issue.readByCurrentUser ? styles.commentIconWithIndicator : styles.commentIcon}
                data-testid={!issue.readByCurrentUser ? 'activity-indicator' : undefined}
              >
                <CommentIcon size={16} data-testid="comment-icon" /> <span>{issue.commentCount}</span>
              </div>
              <span className="sr-only">{issue.commentCount === 1 ? ' comment' : ' comments'}</span>
              {!issue.readByCurrentUser && <span className="sr-only">New activity.</span>}
            </div>
          )}
        </DashboardListItemActions>

        {(issue.repository.copilotAgentEnabled || showCopilotChatActions) && (
          <DashboardListItemTrailingActionsMenu aria-label="Issue actions" anchorRef={actionButtonRef}>
            {issue.repository.copilotAgentEnabled && (
              <DashboardListItemTrailingActionsMenu.Item
                icon={AgentIcon}
                label="Assign to Copilot"
                onClick={onSelectAssignToCopilot}
              />
            )}
            {showCopilotChatActions && (
              <DashboardListItemTrailingActionsMenu.Item
                icon={CopilotIcon}
                label="Open in Copilot Chat"
                onClick={onSelectOpenInCopilotChat}
              />
            )}
          </DashboardListItemTrailingActionsMenu>
        )}
      </DashboardListItem>
    </>
  )
}
