import safeStorage from '@github-ui/safe-storage'
import {QueryQualifier, AgentQueryQualifier, MaxAgeQualifier} from '../types'
import {RESULT_COUNTS} from '../constants'
import {useQuery} from '@github-ui/react-query'
import {getQueryClient} from '@github-ui/react-core/query-client'

const queryKey = ['dashboardStorage']

export class DashboardLocalStorage {
  #NINETY_DAYS_IN_MS = 1000 * 60 * 60 * 24 * 90
  #DASHBOARD_PULL_REQUEST_QUERY_QUALIFIERS_KEY = 'DASHBOARD_PULL_REQUEST_QUERY_QUALIFIERS_KEY'
  #DASHBOARD_PULL_REQUEST_RESULT_COUNT_KEY = 'DASHBOARD_PULL_REQUEST_RESULT_COUNT_KEY'
  #DASHBOARD_PULL_REQUEST_MAX_AGE_KEY = 'DASHBOARD_PULL_REQUEST_MAX_AGE_KEY'
  #DASHBOARD_ISSUE_QUERY_QUALIFIERS_KEY = 'DASHBOARD_ISSUE_QUERY_QUALIFIERS_KEY'
  #DASHBOARD_ISSUE_RESULT_COUNT_KEY = 'DASHBOARD_ISSUE_RESULT_COUNT_KEY'
  #DASHBOARD_ISSUE_MAX_AGE_KEY = 'DASHBOARD_ISSUE_MAX_AGE_KEY'
  #DASHBOARD_AGENT_RESULT_COUNT_KEY = 'DASHBOARD_AGENT_RESULT_COUNT_KEY'
  #DASHBOARD_AGENT_QUERY_QUALIFIERS_KEY = 'DASHBOARD_AGENT_QUERY_QUALIFIERS_KEY'

  #localStorage = safeStorage('localStorage', {
    throwQuotaErrorsOnSet: false,
    ttl: this.#NINETY_DAYS_IN_MS,
  })

  getPullRequestQueryQualifiers(): QueryQualifier[] | null {
    const value = this.#localStorage.getItem(this.#DASHBOARD_PULL_REQUEST_QUERY_QUALIFIERS_KEY)
    if (!value) {
      return null
    }

    try {
      const parsed = JSON.parse(value) as QueryQualifier[]
      return parsed.filter(qualifier => Object.values(QueryQualifier).includes(qualifier))
    } catch {
      return null
    }
  }

  setPullRequestQueryQualifiers(queryQualifiers: QueryQualifier[]) {
    this.#localStorage.setItem(this.#DASHBOARD_PULL_REQUEST_QUERY_QUALIFIERS_KEY, JSON.stringify(queryQualifiers))
    getQueryClient().invalidateQueries({queryKey})
  }

  getPullRequestResultCount(): number | null {
    return this.getResultCountFor(this.#DASHBOARD_PULL_REQUEST_RESULT_COUNT_KEY)
  }

  setPullRequestResultCount(count: number) {
    this.#localStorage.setItem(this.#DASHBOARD_PULL_REQUEST_RESULT_COUNT_KEY, count.toString())
    getQueryClient().invalidateQueries({queryKey})
  }

  getPullRequestMaxAgeQualifier(): MaxAgeQualifier | null {
    const value = this.#localStorage.getItem(this.#DASHBOARD_PULL_REQUEST_MAX_AGE_KEY)
    if (!value) {
      return null
    }

    // Validate that the value is a valid MaxAgeQualifier
    if (Object.values(MaxAgeQualifier).includes(value as MaxAgeQualifier)) {
      return value as MaxAgeQualifier
    }

    return null
  }

  setPullRequestMaxAgeQualifier(maxAgeQualifier: MaxAgeQualifier) {
    this.#localStorage.setItem(this.#DASHBOARD_PULL_REQUEST_MAX_AGE_KEY, maxAgeQualifier)
    getQueryClient().invalidateQueries({queryKey})
  }

  getIssueQueryQualifiers(): QueryQualifier[] | null {
    const value = this.#localStorage.getItem(this.#DASHBOARD_ISSUE_QUERY_QUALIFIERS_KEY)
    if (!value) {
      return null
    }

    try {
      const parsed = JSON.parse(value) as QueryQualifier[]
      return parsed.filter(qualifier => Object.values(QueryQualifier).includes(qualifier))
    } catch {
      return null
    }
  }

  setIssueQueryQualifiers(queryQualifiers: QueryQualifier[]) {
    this.#localStorage.setItem(this.#DASHBOARD_ISSUE_QUERY_QUALIFIERS_KEY, JSON.stringify(queryQualifiers))
    getQueryClient().invalidateQueries({queryKey})
  }

  getIssueResultCount(): number | null {
    return this.getResultCountFor(this.#DASHBOARD_ISSUE_RESULT_COUNT_KEY)
  }

  setIssueResultCount(count: number) {
    this.#localStorage.setItem(this.#DASHBOARD_ISSUE_RESULT_COUNT_KEY, count.toString())
    getQueryClient().invalidateQueries({queryKey})
  }

  getIssueMaxAgeQualifier(): MaxAgeQualifier | null {
    const value = this.#localStorage.getItem(this.#DASHBOARD_ISSUE_MAX_AGE_KEY)
    if (!value) {
      return null
    }

    // Validate that the value is a valid MaxAgeQualifier
    if (Object.values(MaxAgeQualifier).includes(value as MaxAgeQualifier)) {
      return value as MaxAgeQualifier
    }

    return null
  }

  setIssueMaxAgeQualifier(maxAgeQualifier: MaxAgeQualifier) {
    this.#localStorage.setItem(this.#DASHBOARD_ISSUE_MAX_AGE_KEY, maxAgeQualifier)
    getQueryClient().invalidateQueries({queryKey})
  }

  getAgentResultCount(): number | null {
    return this.getResultCountFor(this.#DASHBOARD_AGENT_RESULT_COUNT_KEY)
  }

  setAgentResultCount(count: number) {
    this.#localStorage.setItem(this.#DASHBOARD_AGENT_RESULT_COUNT_KEY, count.toString())
    getQueryClient().invalidateQueries({queryKey})
  }

  getAgentQueryQualifiers(): AgentQueryQualifier[] | null {
    const value = this.#localStorage.getItem(this.#DASHBOARD_AGENT_QUERY_QUALIFIERS_KEY)
    if (!value) {
      return null
    }

    try {
      const parsed = JSON.parse(value) as AgentQueryQualifier[]
      return parsed.filter(qualifier => Object.values(AgentQueryQualifier).includes(qualifier))
    } catch {
      return null
    }
  }

  setAgentQueryQualifiers(queryQualifiers: AgentQueryQualifier[]) {
    this.#localStorage.setItem(this.#DASHBOARD_AGENT_QUERY_QUALIFIERS_KEY, JSON.stringify(queryQualifiers))
    getQueryClient().invalidateQueries({queryKey})
  }

  getResultCountFor(key: string): number | null {
    const value = this.#localStorage.getItem(key)
    if (!value) {
      return null
    }

    const count = parseInt(value, 10)
    if (!RESULT_COUNTS.includes(count)) {
      return null
    }

    return count
  }
}

export const dashboardLocalStorage = new DashboardLocalStorage()

function readDashboardStorage() {
  return {
    pullRequestQueryQualifiers: dashboardLocalStorage.getPullRequestQueryQualifiers(),
    pullRequestResultCount: dashboardLocalStorage.getPullRequestResultCount(),
    pullRequestMaxAgeQualifier: dashboardLocalStorage.getPullRequestMaxAgeQualifier(),
    issueQueryQualifiers: dashboardLocalStorage.getIssueQueryQualifiers(),
    issueResultCount: dashboardLocalStorage.getIssueResultCount(),
    issueMaxAgeQualifier: dashboardLocalStorage.getIssueMaxAgeQualifier(),
    agentResultCount: dashboardLocalStorage.getAgentResultCount(),
    agentQueryQualifiers: dashboardLocalStorage.getAgentQueryQualifiers(),
  }
}

// Marks initial data as fresh so it won't be immediately refetched. Safe with staleTime: Infinity.
// If staleTime is changed to a finite value, initial data will remain fresh for that duration
// rather than triggering an immediate refetch on mount.
function getInitialDataUpdatedAt() {
  return Date.now()
}

export const useDashboardStorage = () =>
  useQuery({
    queryKey,
    queryFn: readDashboardStorage,
    initialData: readDashboardStorage,
    initialDataUpdatedAt: getInitialDataUpdatedAt,
    staleTime: Infinity, // localStorage is the source of truth and only changes via setters, so cache can be infinite
  })
